Lemma sym_execTXB_eq : forall kn0 t K fuel first stops ss,
  s_know ss = kn0 ->
  sym_execTXB (mkbc (facts_of kn0)) t K fuel first stops ss = sym_execTX segs t K fuel first stops ss.
Proof. ltac2:(Rpl.RP.run_k (rplG ()) 0 "S6;A1;i60;i71;A1;k411;r1;A1;k411;r2;A1;k192;A1;k117;r1;A1;k755;r3;A1;k755;r4;Lkn0;R#0;Lt;Rk753;LK;Ri41;Lfuel;Ri41;Lfirst;Ri2;Lstops;RA1;i60;i35;Lss;Ri399;LH;RA3;i1;#0;#1;r7;A6;k8;#0;#2;Lkn0;R#0;A3;i1;i399;A7;k762;#3;r8;r7;r6;r5;r4;r3;A7;k763;vsegs;r8;r7;r6;r5;r4;r3;cdEH;Rm399;RNLs;Ri399;A3;i1;#0;A1;k411;A1;k755;r1;#1;r2;1;Ls_pc;Ri35;Ls_regs;RA1;i60;i32;Ls_log;RA1;i60;i444;Ls_know;RA1;i60;i71;Ls_next;Ri41;Ls_resv;RA1;i70;i93;A6;Ls_pc0;Ri35;Ls_regs0;RA1;i60;i32;Ls_log0;RA1;i60;i444;Ls_know0;R#0;Ls_next0;Ri41;Ls_resv0;RA1;i70;i93;A2;o6;#0;A1;k411;A6;o436;r6;r5;r4;r3;r2;r1;r6;r5;r4;r3;r2;r1;A3;i1;#0;A1;k411;A1;k755;r2;#2;A6;k8;#0;A1;k411;#4;Ll;R#0;A3;i1;i399;A8;k754;#3;r9;r8;r7;r6;r5;#5;#5;A8;k756;vsegs;r9;r8;r7;r6;r5;#5;#5;A7;k764;r8;r7;r6;r5;r4;#4;#4;A1;k411;r3;r1;A3;i1;i399;A7;k762;A1;k192;A1;k117;#2;r7;r6;r5;r4;r3;r2;A7;k763;vsegs;r7;r6;r5;r4;r3;r2;r8;r1;").
