Definition nt_empty : ntab := ltac2:(Rpl.RP.run_k (rplG ()) 0 "S1;A2;i91;i32;i466;A4;o836;A1;o62;A1;i60;#0;A1;o62;#0;o150;A1;o598;i837;").
Fixpoint alookupE (l : list (expr * positive)) (b : expr) : option positive :=
  match l with
  | [] => None
  | (b', id) :: rest => if expr_eqb b b' then Some id else alookupE rest b
  end.
