Fixpoint scan_entries (bc : bctx) (kn : list kentry) (t : ntab) (gs : gst) : list (option einfo) * ntab * gst :=
  match kn with
  | [] => ([], t, gs)
  | K :: rest =>
      match kdescr K with
      | Some (kb, kk, om) =>
          let '(r, t1) := intern bc t kb in
          let '(bid, bi) := r in
          let '(gid, gs1) := match om with
                             | Some m => let '(gid, gs0) := ggroup gs bid kk in (gid, bnd_add gs0 gid bid (bi_br bi) kk (kk + m)%Z)
                             | None => (xH, gs)
                             end in
          let '(infos, t2, gs2) := scan_entries bc rest t1 gs1 in
          (Some (EI bid gid kb (bi_br bi) kk om) :: infos, t2, gs2)
      | None =>
          let '(infos, t2, gs2) := scan_entries bc rest t gs in
          (None :: infos, t2, gs2)
      end
  end.

Definition sx_m1 (sx : stx) : Z := ltac2:(Rpl.RP.run_k (rplG ()) 1 "S0;Lsx;Ri868;A1;k206;A1;k156;A1;k871;r1;").

Definition verdict (sx : stx) (g : gval) : bool := ltac2:(Rpl.RP.run_k (rplG ()) 2 "S3;A2;i91;i35;i35;A1;i70;#0;A1;k222;A1;k870;r14;Lsx;Ri868;Lg;Rk930;m91;RNLg;RA2;i91;A2;i91;i466;#1;#0;i2;r1;1;Lp;RA2;i91;i466;#1;Lp0;R#0;m91;RNLp;RA2;i91;i466;#1;i2;r2;1;Lb;Ri466;Lobr;R#1;m91;RNLp0;RA2;i91;i35;i35;i2;r3;1;Lglo;Ri35;Lghi;Ri35;m2;RNL~Ri2;i2;A2;k866;r4;A1;k893;r8;2;o7;m70;RNLx;RA1;i70;#0;i2;A1;k238;A1;k869;r8;2;Lp;R#0;m91;RNLp;RA2;i91;i35;i35;i2;r1;1;Llo1;Ri35;Lhi1;Ri35;m70;RNLobr;RA1;i70;#0;i2;r6;2;Lp0;R#0;m91;RNLp0;RA2;i91;i35;i35;i2;r1;1;Llo2;Ri35;Lhi2;Ri35;A2;k155;A2;k100;A2;k106;A2;k105;A2;k105;r4;#2;A1;k938;r14;r2;r8;A2;k100;r7;A2;k106;A2;k105;r5;#2;r1;o7;o7;").

Fixpoint mk_fl (g : gval) (sxs : list stx) : list (stx * list stx) :=
  match sxs with
  | [] => []
  | sx :: rest => if verdict sx g then mk_fl g rest else (sx, rest) :: mk_fl g rest
  end.
Definition gfl : Type := ltac2:(Rpl.RP.run_k (rplG ()) 0 "U0;A2;i91;k930;A1;i60;A2;i91;i868;A1;i60;i868;").
